import {installCollectorHistory} from './collector-navigation.js';
import {issueStep} from './collector-errors.js';
import {icon} from './desktop-icons.js';
import {visibleCollectorUnits,unitStateLabel} from './collector-unit-list.js';
import {groups,sections,categories,audiovisual,equipmentFields,shown,validateFields,validateEquipment,sectionProblems,sectionStages} from './collector-schema.js';
const app=document.querySelector('#collector'),$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

let capabilities={photosEnabled:false},me,view='units',collection=null,group='A',step=0,answers={},equipment=null,equipmentStep=0,lockToken=null,equipmentVersion=0,dirty=false,busy=false,saveLabel='',errorFields={},notice='',units=[],unitQuery='',items=[],nextCursor=null,cursors=[null],equipmentQuery='',categoryFilter='',verificationFilter='',menu=false,saveTimer,saveQueue=Promise.resolve(),lockTimer,sheetContext=null;
const pendingPhotos=new Map(),photoLists=new Map(),photoContexts=new Map();let cachedInspectionId=null,navigation,returnToReview=false,unitTab='pending',environmentDraft={name:'',type:'Outro ambiente'};
const button=(label,action,cls='primary',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const categoryName=id=>categories.find(c=>c[0]===id)?.[1]||id;
function toast(text){$('.toast')?.remove();const t=document.createElement('div');t.className='toast';t.role='status';t.textContent=text;document.body.append(t);setTimeout(()=>t.remove(),6500);}
async function rawApi(path,data,options={},retried=false){const response=await fetch(path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json','X-CSRF-Token':me?.csrf||''}:{},body:data?JSON.stringify(data):undefined,...options});let value;try{value=await response.json();}catch{throw Error('O servidor não confirmou a operação. As respostas nesta tela foram preservadas.');}if(!response.ok){if(response.status===403&&!retried&&me){const check=await fetch('/api/auth/me');if(check.ok){const fresh=await check.json();if(fresh.username===me.username&&fresh.csrf!==me.csrf){me=fresh;return api(path,data,options,true);}}}if(response.status===401)value.error='Sessão expirada. Entre novamente em outra aba e retorne para tentar salvar, sem fechar esta tela.';const error=Error(value.error||'Operação não confirmada.');Object.assign(error,value);throw error;}return value;}
let networkRequests=0;
async function api(...args){networkRequests++;let indicator=document.querySelector('#network-status');if(!indicator){indicator=document.createElement('div');indicator.id='network-status';indicator.className='network-status';indicator.role='status';document.body.append(indicator);}indicator.textContent=args[1]?'Salvando…':'Carregando…';indicator.hidden=false;try{return await rawApi(...args);}finally{if(--networkRequests===0)indicator.hidden=true;}}
function header(title,subtitle='',back=true,progress=null){return `<header class="app-header"><div class="header-row">${back?button(icon('back'),'back','icon-button','aria-label="Voltar"'):''}<div class="header-title"><h1>${esc(title)}</h1><small>${esc(subtitle)}</small></div><span class="save-state" data-save-state>${esc(saveLabel)}</span>${button(icon('down'),'account','icon-button','aria-label="Minha conta e sair"')}</div>${collection&&!['units','cards'].includes(view)?button('← Categorias','return-categories','category-return','aria-label="Voltar às categorias"'):''}${progress?`<div class="progress">Etapa ${progress[0]+1} de ${progress[1]}<div class="progress-segments">${Array.from({length:progress[1]},(_,i)=>`<i class="${i<=progress[0]?'filled':''}"></i>`).join('')}</div></div>`:''}</header>`;}
const footer=content=>`<footer class="collection-footer">${content}</footer>`;
const input=(name,label,value='',type='text')=>`<label class="field"><span>${esc(label)}</span><input name="${name}" value="${esc(value)}" type="${type}" autocomplete="off"></label>`;
function status(text){saveLabel=text;const n=$('[data-save-state]');if(n)n.textContent=text;}
function get(data,path){return path.split('.').reduce((v,k)=>v?.[k],data);}
function set(data,path,value){const keys=path.split('.');let current=data;for(const k of keys.slice(0,-1)){if(['__proto__','constructor','prototype'].includes(k))return;current=current[k]??=(/^\d+$/.test(keys[keys.indexOf(k)+1])?[]:{});}current[keys.at(-1)]=value;}
const currentData=()=>view==='equipment'?equipment.data:answers;
const context=()=>({environments:collection?.environments||[],hasProblems:!!collection?.totals?.problems||['C','D','E'].some(g=>sectionProblems(g,g===group?answers:collection?.sections[g]?.data||{}))});
function required(field,data){return typeof field.required==='function'?field.required(data,context()):field.required;}
function fieldsForGroup(){return (sections[group]||[]).filter(f=>shown(f,answers,context()));}
function valueLabel(f,value){if(f.type==='environment')return collection.environments.find(e=>e.id===value)?.name||'';if(f.type==='environments')return (value||[]).map(id=>collection.environments.find(e=>e.id===id)?.name||id).join(', ');if(f.key==='category')return categoryName(value);return String(value??'');}
function photoTarget(kind,id){return kind+':'+id;}
function photosBlock(kind,id){if(kind==='equipment'&&equipment?.id===id&&equipment.data.mode==='Lote')return '<div class="notice">A quantidade de fotos por lote ainda aguarda definição. Para fotografias individuais nesta etapa, utilize fichas individuais.</div>';const key=photoTarget(kind,id),saved=photoLists.get(key)||[],pending=pendingPhotos.get(key)||[];return `<div class="photos-block">${!capabilities.photosEnabled?'<div class="notice">Armazenamento não conectado. Você pode preparar prévias nesta aba, mas elas ainda não serão enviadas. Não feche a aba antes de enviar.</div>':''}<p class="help">${kind==='equipment'?'Fotografias opcionais · até 5 por equipamento.':kind==='occurrence'?'Falha visível: envie foto ou justifique quando não for possível ou seguro.':'Fotografias vinculadas a este registro · câmera ou galeria.'}</p><button type="button" class="photo-box" data-photo-picker="${esc(key)}" data-camera="true">${icon('camera')}Fotografar</button><button type="button" class="secondary" data-photo-picker="${esc(key)}">Escolher da galeria</button><input hidden type="file" accept="image/*" data-photo-file="${esc(key)}" capture="environment"><input hidden type="file" accept="image/*" multiple data-photo-gallery="${esc(key)}"><div class="photos">${saved.map(p=>`<div class="photo-thumb">${p.status==='ready'?`<img loading="lazy" src="/api/collector/photo?id=${encodeURIComponent(p.id)}" alt="Fotografia vinculada ao registro">`:'<p>Envio pendente no servidor</p>'}${p.status==='ready'?button('Remover foto','remove-photo','text-button',`data-id="${p.id}" data-target="${key}"`):''}</div>`).join('')}${pending.map((p,index)=>`<div class="photo-thumb"><img src="${p.preview}" alt="Prévia da foto ainda não enviada">${button('Remover prévia','remove-preview','text-button',`data-target="${key}" data-index="${index}"`)}</div>`).join('')}</div>${pending.length?button('Enviar '+pending.length+' foto(s)','upload-photos','primary',`data-target="${key}" ${!capabilities.photosEnabled?'disabled':''}`):''}<p class="help">A prévia ainda não enviada permanece somente nesta aba. Envie antes de fechar.</p></div>`;}
function facade(){return header('Fachada da unidade',collection.unit.name)+ '<main class="content"><h2>Comece pela fachada</h2><p>Fotografe a entrada e a identificação da unidade selecionada.</p>'+photosBlock('facade',collection.unit.id)+'</main>'+footer(button('Trocar unidade','change-unit','secondary')+button('Continuar · acompanhante','start-identification'));}
function evidenceControl(key,label,rowPath=''){const id=answers._photoEvidence?.[key];return '<section class="summary-card"><h3>'+esc(label)+'</h3>'+(id?photosBlock('answer',id):button(icon('camera')+' Fotografar este registro','add-evidence','secondary',`data-evidence="${esc(key)}" data-evidence-row="${esc(rowPath)}"`))+'</section>';}
function stageEvidence(fields){return ['C','D','E','H'].includes(group)?fields.filter(f=>shown(f,answers,context())&&!['rows','occurrences'].includes(f.type)).map(f=>evidenceControl(group+'.'+f.key,'Evidência · '+f.label)).join(''):'';}
function drawField(f,data,path=f.key,main=false){if(!shown(f,data,context()))return '';if(view==='group'&&['environment','environments'].includes(f.type)&&!collection.environments.length&&!required(f,data))return '';const value=data[f.key],id='field-'+path.replaceAll('.','-'),err=errorFields[path],title=`${esc(f.label)}${required(f,data)?' <span class="required">*</span>':''}`,attrs=`data-field="${path}" id="${id}" aria-describedby="${id}-error" aria-invalid="${!!err}"`;
 if(['rows','occurrences'].includes(f.type)){const rows=Array.isArray(value)?value:[];return `<section><h2>${esc(f.label)}</h2>${rows.map((row,i)=>`<div class="repeat-row"><strong>Registro ${i+1}</strong>${f.children.map(child=>drawField(child,row,path+'.'+i+'.'+child.key)).join('')}${f.type==='occurrences'?photosBlock('occurrence',row.id):evidenceControl(group+'.'+path+'.'+(row.id||'legacy-'+i),'Fotos deste registro',path+'.'+i)}${button('Remover este registro','remove-row','text-button',`data-path="${path}" data-index="${i}"`)}</div>`).join('')}${button('+ Adicionar registro','add-row','secondary',`data-path="${path}" data-occurrence="${f.type==='occurrences'}"`)}<span class="field-error">${esc(err||'')}</span>${f.type==='rows'&&!rows.length?'<p class="help">Adicione os registros aplicáveis. Não preencha exemplos fictícios.</p>':''}</section>`;}
 if(f.type==='checkbox')return `<label class="checkbox-field"><input type="checkbox" ${attrs} ${value?'checked':''}>${title}</label>`;
 if(main&&f.type==='select'&&f.options.length<=6&&f.key!=='category')return `<div><h2>${esc(f.label)}</h2>${f.options.map(option=>`<button type="button" class="option ${value===option?'selected':''}" data-choice="${path}" data-value="${esc(option)}">${esc(option)}<span class="radio">${value===option?icon('check'):''}</span></button>`).join('')}<span class="field-error" id="${id}-error">${esc(err||'')}</span></div>`;
 if(['select','environment','environments'].includes(f.type))return `<label class="field"><span>${title}</span><button type="button" class="sheet-select" ${attrs} data-sheet="${path}" data-sheet-type="${f.type}" data-options="${esc(JSON.stringify(f.options||[]))}" data-title="${esc(f.label)}">${esc(valueLabel(f,value)||'Toque para escolher')}${icon('down')}</button><span class="field-error" id="${id}-error">${esc(err||'')}</span></label>${['environment','environments'].includes(f.type)&&!collection.environments.length?'<div class="notice">Cadastre os ambientes no grupo B para selecionar aqui.'+button('Abrir ambientes','open-environments','text-button')+'</div>':''}`;
 return `<label class="field"><span>${title}</span>${f.type==='textarea'?`<textarea ${attrs} maxlength="4000">${esc(value||'')}</textarea>`:`<input ${attrs} type="${['number','decimal'].includes(f.type)?'text':f.type==='datetime-local'?'datetime-local':'text'}" ${f.type==='digits'?'inputmode="numeric" pattern="[0-9]*"':(['number','decimal'].includes(f.type)?'inputmode="decimal"':'')} value="${esc(value??'')}" maxlength="4000" ${['asset','serial','brand','model','provider','contracted'].includes(f.key)?`list="suggestions-${f.key}"`:''}>`}<span class="field-error" id="${id}-error">${esc(err||'')}</span></label>`;
}
function photoQueue(){return header('Fotografias pendentes','Prévias ainda não enviadas')+'<main class="content">'+[...pendingPhotos.entries()].filter(([,list])=>list.length).map(([key,list])=>'<section class="summary-card"><h2>'+esc(photoContexts.get(key)?.caption||'Fotografias do registro')+'</h2><div class="photos">'+list.map((photo,index)=>'<div class="photo-thumb"><img src="'+photo.preview+'" alt="Prévia não enviada">'+button('Remover prévia','remove-preview','text-button','data-target="'+key+'" data-index="'+index+'"')+'</div>').join('')+'</div>'+button('Enviar fotografias','upload-photos','primary','data-target="'+key+'"')+'</section>').join('')+'<p class="help">Essas prévias estão somente nesta aba. O armazenamento offline protegido ainda não está disponível.</p></main>'+footer(button('Voltar às categorias','cards','secondary'));}
function drawUnits(){
 const pending=visibleCollectorUnits(units).length,received=visibleCollectorUnits(units,'','received').length;
 return `${header('Coleta Escolar',me.displayName||me.username,false)}<main class="content unit-selection"><div class="unit-intro"><h2>Selecione a unidade</h2><p>Ela ficará ativa durante toda a coleta.</p></div><label class="field unit-search"><span class="sr">Filtrar unidades por nome ou INEP</span>${icon('search')}<input id="unit-search" type="search" placeholder="Nome da unidade ou INEP" value="${esc(unitQuery)}"></label><nav class="unit-tabs" aria-label="Situação do inventário"><button data-action="unit-tab" data-tab="pending" aria-pressed="${unitTab==='pending'}">Pendentes <span>${pending}</span></button>${received?`<button data-action="unit-tab" data-tab="received" aria-pressed="${unitTab==='received'}">Com inventário <span>${received}</span></button>`:''}</nav><p class="help"><span data-unit-filter-count>${visibleCollectorUnits(units,unitQuery,unitTab).length}</span> unidade(s) exibida(s)</p><div id="unit-results" aria-live="polite">${unitResults()}</div><p class="help">Escolha uma unidade da lista para iniciar ou continuar o preenchimento. É necessário ter conexão para salvar.</p>${!capabilities.photosEnabled?'<div class="notice">Fotografias aguardam a habilitação do armazenamento. Os questionários e equipamentos podem ser registrados online.</div>':''}</main>`;
}
function unitResults(){return visibleCollectorUnits(units,unitQuery,unitTab).map(u=>`<button class="unit-card" data-action="select-unit" data-id="${esc(u.id)}"><span class="round-icon">${icon('building')}</span><span><strong>${esc(u.name)}</strong><small>${esc(['Paço do Lumiar',u.code?'INEP '+u.code:u.unit_type||'Unidade cadastrada'].join(' · '))}</small><small class="unit-status">${unitStateLabel(u)}</small></span>${icon('chevron')}</button>`).join('')||`<div class="empty">${unitQuery?'Nenhuma unidade corresponde ao filtro.':unitTab==='pending'?'Nenhuma unidade com inventário de equipamentos pendente.':'Nenhuma unidade com inventário recebido disponível para esta conta.'}</div>`;}
function cards(){return `${header('Categorias',collection.unit.name,false)}<main class="content">${equipment?'<div class="notice">Ficha de equipamento preservada nesta aba. '+button('Retomar ficha em preenchimento','resume-equipment','secondary')+'</div>':''}${button(icon('camera')+' Fachada da unidade','show-facade','secondary full')}<p class="help">Ordem sugerida: internet → rede → ambientes → energia → equipamentos. As fotos acompanham cada registro.</p><div class="cards">${groups.map(([id,name,glyph])=>{const state=collection.sections[id]?.state||'Pendente';return `<button class="category-card" data-action="open-group" data-group="${id}"><span class="category-icon">${icon(glyph)}</span>${icon('chevron')}<strong>${id} · ${esc(name)}</strong><span class="state ${state==='Concluído'?'done':state==='Em andamento'?'working':''}">${state}</span></button>`;}).join('')}</div>${[...pendingPhotos.values()].some(p=>p.length)?button('Fotografias pendentes nesta aba','photo-queue','secondary'):''}<button class="fab ${menu?'above':''}" data-action="fab" aria-label="Adicionar registro">${menu?'×':'+'}</button><p class="help">${collection.totals.records} ficha(s) · ${collection.totals.items} equipamento(s) registrados nesta unidade. Rascunhos não são resultados oficiais.</p>${collection.inspection.state==='completed'?'<div class="notice success">Vistoria concluída e recebida pelo servidor.</div>':''}</main>${footer(button('Trocar unidade','change-unit','secondary')+button('Revisar vistoria','review'))}${menu?'<div class="backdrop" data-action="fab"></div><div class="fab-menu">'+button(icon('monitor')+' Adicionar equipamento','new-equipment','')+button(icon('rooms')+' Cadastrar ambiente','open-environments','')+button(icon('wifi')+' Internet e conectividade','open-group','', 'data-group="C"')+'</div>':''}`;}
function environmentEditor(){return `<div class="summary-card"><h3>Ambientes identificados</h3>${collection.environments.map(e=>`<p><strong>${esc(e.name)}</strong> · ${esc(e.type)}</p>${photosBlock('environment',e.id)}`).join('')||'<p>Nenhum ambiente identificado.</p>'}<form id="environment-form">${input('name','Nome do ambiente',environmentDraft.name)}${input('type','Tipo do ambiente',environmentDraft.type)}<button class="secondary" type="submit">+ Cadastrar ambiente</button></form>${equipment?button('Retomar ficha do equipamento','resume-equipment','text-button'):''}</div>`;}
function groupWizard(){const stages=sectionStages(group,answers,context());step=Math.max(0,Math.min(step,stages.length-1));const fields=stages[step]||[],isLast=step===stages.length-1;return `${header(groups.find(g=>g[0]===group)[1],collection.unit.name,true,[step,Math.max(1,stages.length)])}<main class="content">${group==='A'?`<div class="summary-card"><strong>${esc(collection.unit.name)}</strong><p>Operador: ${esc(me.username)}<br>Vistoria iniciada: ${new Date(collection.inspection.created_at).toLocaleString('pt-BR')}</p></div>`:''}${group==='B'?environmentEditor():''}${group==='D'?'<p class="help">Roteadores/APs/switches também cadastrados em F são os mesmos bens. As quantidades de infraestrutura não são somadas novamente ao patrimônio.</p>':''}${group==='E'?'<p class="help">Avaliação visual das instalações. Os registros em lote não duplicam equipamentos já cadastrados em F.</p>':''}${group==='H'?`<div class="notice">Problemas de C/D/E e dos equipamentos são consolidados sem recadastro. ${button('Consultar fichas dos equipamentos','inventory','text-button')}</div>`:''}${fields.map(field=>drawField(field,answers,field.key,true)+stageEvidence([field])).join('')}${Object.keys(errorFields).length?'<div class="notice error">Existem pendências neste cartão. '+Object.values(errorFields).map(esc).join(' ')+'</div>':''}</main>${footer(button(returnToReview&&step===0?'Voltar à revisão':'← Voltar','previous','secondary')+button(isLast?'Marcar como concluído':'Próximo →',isLast?'complete-section':'next')+button('Salvar rascunho','save-section','text-button full'))}`;}
function inventory(){return `${header(group==='G'?'Recursos audiovisuais':'Equipamentos',collection.unit.name)}<main class="content"><h2>Conferir ou adicionar</h2><p class="help">Cadastro contínuo, sem limite fixo de fichas por unidade. São exibidos até 50 registros por página.</p><label class="field"><span>Buscar patrimônio, série, marca ou modelo</span><input id="equipment-search" type="search" value="${esc(equipmentQuery)}" placeholder="Buscar equipamento"></label><label class="field"><span>Conferência nesta visita</span><select id="verification-filter"><option value="">Todos os registros</option><option value="unverified" ${verificationFilter==='unverified'?'selected':''}>Não conferidos / não verificados</option><option value="missing" ${verificationFilter==='missing'?'selected':''}>Não localizados</option></select></label><label class="field"><span>Categoria</span><select id="category-filter"><option value="${group==='G'?'audiovisual':''}">${group==='G'?'Todos os audiovisuais':'Todas'}</option>${categories.filter(c=>group!=='G'||audiovisual.includes(c[0])).map(c=>`<option value="${c[0]}" ${categoryFilter===c[0]?'selected':''}>${esc(c[1])}</option>`).join('')}</select></label>${equipment?button('Retomar ficha em preenchimento','resume-equipment','secondary'):''}<div id="equipment-list">${items.map(row=>`<article class="equipment-card"><h3>${esc(categoryName(row.category))}${row.data.mode==='Lote'?' · lote de '+esc(row.data.quantity):''}</h3><p>Patrimônio: ${esc(row.asset)}<br>Série: ${esc(row.serial)}<br>${esc(row.data.operation)} · ${esc(row.data.use)}</p><p>Última alteração: ${new Date(row.updated_at).toLocaleString('pt-BR')}<br>Última verificação: ${row.verified_at?new Date(row.verified_at).toLocaleString('pt-BR'):'Não verificado'}</p><p class="state">${esc(row.verification||'Não conferido nesta vistoria')}${row.duplicate_flag?' · Duplicidade em análise':''}</p><div class="actions">${button('Editar ficha','edit-equipment','secondary',`data-id="${row.id}"`)}${button('Conferir sem alterar','verify-equipment','secondary',`data-id="${row.id}" data-result="Verificado sem alterações"`)}${button('Não localizado','verify-equipment','text-button',`data-id="${row.id}" data-result="Não localizado"`)}${button('Não verificado','verify-equipment','text-button',`data-id="${row.id}" data-result="Não verificado"`)}</div></article>`).join('')||'<div class="empty">Nenhum equipamento encontrado neste filtro.</div>'}</div><div class="pagination">${button('← Anterior','previous-page','secondary',cursors.length===1?'disabled':'')}${button('Próxima →','next-page','secondary',!nextCursor?'disabled':'')}</div></main>${footer(button('+ Adicionar equipamento','new-equipment')+button('Concluir cartão '+group,'complete-inventory','secondary'))}`;}
function equipmentSteps(){const fields=equipmentFields.filter(f=>shown(f,equipment.data,context()));return [fields.filter(f=>['category','customCategory'].includes(f.key)),fields.filter(f=>['mode','quantity','environment'].includes(f.key)&&!(f.key==='mode'&&categories.find(c=>c[0]===equipment.data.category)?.[2]==='individual')),fields.filter(f=>['asset','serial','brand','model','anydesk','rustdesk'].includes(f.key)),fields.filter(f=>['condition','operation','use','problems','action','otherAction','priority','notes'].includes(f.key)),[],[]];}
function equipmentWizard(){const data=equipment.data,steps=equipmentSteps(),fields=steps[equipmentStep],category=categories.find(c=>c[0]===data.category),key=photoTarget('equipment',equipment.id);return `${header(category?.[1]||'Novo equipamento',collection.unit.name,true,[equipmentStep,steps.length])}<main class="content"><h2>${['Qual é o equipamento?','Onde está o equipamento?','Identificação do equipamento','Condições e problemas','Detalhes técnicos opcionais','Fotografias do equipamento'][equipmentStep]}</h2>${fields.map(f=>drawField(f,data,f.key,equipmentStep===0)).join('')}${equipmentStep===2?'<div class="inline-actions">'+button('Sem patrimônio','fill-asset','text-button')+button('Sem número de série','fill-serial','text-button')+button('Marca/modelo não identificados','fill-identification','text-button')+'</div>':''}${equipmentStep===4?(category?.[3].map(label=>input('tech-'+label,label+' (opcional)',data.technical?.[label]||'')).join('')||'<p>Esta categoria não exige especificações técnicas adicionais.</p>'):''}${equipmentStep>=2?'<section class="summary-card"><h3>Evidências deste equipamento</h3>'+photosBlock('equipment',equipment.id)+'</section>':''}${Object.keys(errorFields).length?'<div class="notice error">'+Object.values(errorFields).map(esc).join(' ')+'</div>':''}${notice?'<div class="notice error">'+esc(notice)+'</div>':''}${equipment.saved?'<div class="notice success">Equipamento salvo no servidor como rascunho de vistoria. '+(pendingPhotos.get(key)?.length?'Existem fotos ainda não enviadas.':'')+'</div>':''}</main>${footer(button('← Voltar','equipment-previous','secondary')+(equipmentStep===5?button('Salvar e adicionar outro','save-add-another')+button('Salvar e voltar às categorias','save-equipment','secondary full'):button('Próximo →','equipment-next')))}${datalists()}`;}
function datalists(){return ['asset','serial','brand','model','provider','contracted'].map(key=>`<datalist id="suggestions-${key}">${({asset:['Sem patrimônio','Não identificado'],serial:['Sem número de série','Não identificado'],brand:['Outra marca','Não identificado'],model:['Não identificado'],provider:['Outra operadora','Não soube informar'],contracted:['Não soube informar']}[key]).map(v=>'<option value="'+esc(v)+'"></option>').join('')}</datalist>`).join('');}
let reviewData=null;
function review(){return header('Revisão da vistoria',collection.unit.name)+'<main class="content"><h2>Confira antes de concluir</h2>'+groups.map(([g,name])=>{const details=reviewData?.details?.[g]||{},keys=Object.keys(details);return '<section class="summary-card"><strong>'+g+' · '+esc(name)+'</strong><p>'+esc(collection.sections[g]?.state||'Pendente')+'</p>'+(keys.length?'<ul class="review-issues">'+keys.map(key=>'<li>'+button(esc(details[key]),'open-group','text-button','data-group="'+g+'" data-error-key="'+esc(key)+'"')+'</li>').join('')+'</ul>':reviewData?.errors[g]?'<p class="field-error">'+esc(reviewData.errors[g])+'</p>':'')+button(keys.length?'Corrigir primeira pendência':'Abrir cartão','open-group','text-button','data-group="'+g+'"')+'</section>';}).join('')+'<div class="notice">'+(reviewData?.unverified||0)+' equipamento(s) não conferido(s) nesta visita. '+button('Ver equipamentos não conferidos','show-unverified','text-button')+' Não conferido não significa não localizado.<br>'+(reviewData?.missing||0)+' registro(s) não localizado(s), com justificativas no histórico.</div><p>Confirme somente depois de revisar os cartões. A conclusão será informada após o servidor confirmar.</p>'+(collection.inspection.state==='completed'?'<div class="notice success">Vistoria concluída e recebida pelo servidor.</div>':'')+'</main>'+footer(button('Voltar às categorias','cards','secondary')+button('Confirmar conclusão','finish',Object.keys(reviewData?.errors||{}).length?'secondary':'primary',Object.keys(reviewData?.errors||{}).length||collection.inspection.state==='completed'?'disabled':''));}
function render(){const focused=document.activeElement?.id==='equipment-search',caret=focused?document.activeElement.selectionStart:null;app.innerHTML=(view==='units'?drawUnits():view==='facade'?facade():view==='cards'?cards():view==='group'?groupWizard():view==='inventory'?inventory():view==='equipment'?equipmentWizard():view==='photo-queue'?photoQueue():review())+datalists();if(notice&&view!=='equipment'){const n=document.createElement('div');n.className='notice error';n.role='alert';n.textContent=notice;$('.content')?.prepend(n);}if(focused){const search=document.querySelector('#equipment-search');search?.focus();if(search&&caret!==null)search.setSelectionRange(caret,caret);}document.title=(view==='units'?'Coleta SEMED':view==='cards'?'Categorias':view==='inventory'?(group==='G'?'Recursos audiovisuais':'Equipamentos'):view==='equipment'?'Ficha de equipamento':view==='review'?'Revisão':groups.find(g=>g[0]===group)?.[1]||'Coleta')+' · SEMED';}
function repaint(){render();navigation?.remember();window.scrollTo({top:0,behavior:'instant'});}
function readRoute(){return collection?{inspectionId:collection.inspection.id,view:view==='equipment'?'inventory':view,group,step,returnReview:returnToReview}:{view:'units'};}
async function showReview(){await loadCollection();reviewData=await api('/api/collector/review?id='+collection.inspection.id);view='review';returnToReview=false;repaint();}
async function restoreRoute(route){
 const hadCollection=!!collection;clearTimeout(saveTimer);if(view==='group'&&dirty&&collection)await saveSection();await saveQueue;await releaseLock();
 notice='';errorFields={};menu=false;
 if(!route.inspectionId){if(hadCollection)units=(await api('/api/units')).units;view='units';collection=null;returnToReview=false;dirty=false;render();return;}
 collection={inspection:{id:route.inspectionId}};
 try{await loadCollection();}catch(error){collection=null;view='units';render();throw error;}
 group=route.group||'A';step=route.step||0;returnToReview=!!route.returnReview;view=route.view||'cards';dirty=false;
 if(view==='group'){
  if(!sections[group]||collection.sections[group].state==='Concluído'){view='cards';returnToReview=false;}
  else answers=structuredClone(collection.sections[group].data||{});
 }
 if(view==='inventory'){if(!['F','G'].includes(group))group='F';categoryFilter=group==='G'?'audiovisual':'';cursors=[null];await loadItems();}
 if(view==='review'){reviewData=await api('/api/collector/review?id='+collection.inspection.id);returnToReview=false;}
 status(collection.inspection.state==='completed'?'Vistoria recebida':'Rascunho no servidor');render();
}
async function loadCollection(){collection=await api('/api/collector/inspection?id='+collection.inspection.id);if(cachedInspectionId!==collection.inspection.id){photoLists.clear();cachedInspectionId=collection.inspection.id;}if(collection.inspection.questionnaire_version==='coleta-3.0'){location.replace('/coleta-v3?vistoria='+encodeURIComponent(collection.inspection.id));return;}if(collection.inspection.questionnaire_version==='coleta-2.0'){location.replace('/coleta-v2?vistoria='+encodeURIComponent(collection.inspection.id));return;}if(collection.inspection.questionnaire_version==='visita-2'){location.replace('/visita?vistoria='+encodeURIComponent(collection.inspection.id));return;}for(const row of collection.photos||[]){const key=photoTarget(row.target_kind,row.target_id),list=photoLists.get(key)||[];if(!list.some(p=>p.id===row.id))list.push(row);photoLists.set(key,list);}}
function scheduleSave(){dirty=true;status('Alterações nesta aba');clearTimeout(saveTimer);if(view==='group')saveTimer=setTimeout(()=>saveSection().catch(showError),1000);}
async function saveSection(complete=false,reopen=false){clearTimeout(saveTimer);const g=group,content=structuredClone(answers),i=collection.inspection.id;const work=async()=>{if(!complete&&!reopen&&JSON.stringify(content)===JSON.stringify(collection.sections[g].data||{})){if(g===group)dirty=false;return true;}status('Salvando…');try{const result=await api('/api/collector/section-save',{inspectionId:i,section:g,version:collection.sections[g].version,answers:content,complete,reopen});Object.assign(collection.sections[g],result);collection.sections[g].data=content;if(g===group&&!complete&&!reopen){const remaining=validateFields(sections[g]||[],answers,context());errorFields=Object.fromEntries(Object.entries(errorFields).filter(([key])=>remaining[key]||key.startsWith('photo-')||key==='links'));}if(g===group&&JSON.stringify(answers)===JSON.stringify(content))dirty=false;status('Rascunho no servidor');if(complete){await loadCollection();errorFields={};if(returnToReview)await showReview();else{view='cards';repaint();}}return true;}catch(error){dirty=true;status('Não salvo');throw error;}};const queued=saveQueue.then(work,work);saveQueue=queued.catch(()=>{});return queued;}
function showError(error){notice=error.message;errorFields=error.fields||{};if(error.conflict){const dialog=document.createElement('dialog');dialog.innerHTML='<h2>Conflito de edição</h2><p>Suas respostas continuam nesta tela e foram guardadas para análise. O servidor preservou a outra versão.</p><pre>'+esc(JSON.stringify(error.server,null,2))+'</pre>'+button('Fechar e revisar','close-dialog','secondary');document.body.append(dialog);dialog.showModal();}render();if(error.duplicateId){const n=document.createElement('div');n.className='notice';n.innerHTML=button('Abrir registro existente','edit-equipment','secondary',`data-id="${error.duplicateId}"`)+button('Justificar novo registro para análise','justify-duplicate','text-button');$('.content').append(n);}if(view==='group'){const index=fieldsForGroup().findIndex(f=>Object.keys(errorFields).some(k=>k===f.key||k.startsWith(f.key+'.')));if(index>=0){step=issueStep(group,Object.keys(errorFields)[0],answers,context());render();}}}
async function confirmAction(title,text){return new Promise(resolve=>{const d=document.createElement('dialog');d.innerHTML=`<h2>${esc(title)}</h2><p>${esc(text)}</p><div class="actions"><button class="secondary" data-result="no">Cancelar</button><button class="primary" data-result="yes">Confirmar</button></div>`;d.addEventListener('click',e=>{const answer=e.target.closest('[data-result]');if(answer){d.close();d.remove();resolve(answer.dataset.result==='yes');}});d.addEventListener('cancel',()=>{d.remove();resolve(false);});document.body.append(d);d.showModal();});}
async function leave(){clearTimeout(saveTimer);if(view==='group'&&dirty)await saveSection();await releaseLock();notice='';errorFields={};return true;}
async function openGroup(g,focusKey=null){const fromReview=view==='review';if(!await leave())return;if(collection.inspection.state!=='open'){toast('Esta vistoria já está concluída. Troque de unidade e inicie uma nova visita para atualizar.');return;}menu=false;group=g;step=0;answers=structuredClone(collection.sections[g].data||{});if(collection.sections[g].state==='Concluído'){if(!await confirmAction('Reabrir cartão '+g+'?','O cartão voltará a Em andamento e precisará ser concluído manualmente outra vez.'))return;if(['F','G'].includes(g)){await api('/api/collector/inventory-section',{inspectionId:collection.inspection.id,section:g,version:collection.sections[g].version,reopen:true});await loadCollection();}else{await saveSection(false,true);answers=structuredClone(collection.sections[g].data);}}dirty=false;returnToReview=fromReview;view=['F','G'].includes(g)?'inventory':'group';if(view==='group'&&fromReview){const fields=reviewData?.details?.[g]||{};const key=focusKey||Object.keys(fields)[0];step=issueStep(g,key,answers,context());errorFields=fields;}if(view==='inventory'){equipmentQuery='';categoryFilter=group==='G'?'audiovisual':'';cursors=[null];await loadItems();}repaint();}
async function loadItems(){const params=new URLSearchParams({unitId:collection.unit.id,inspectionId:collection.inspection.id,q:equipmentQuery,category:categoryFilter,verification:verificationFilter,cursor:cursors.at(-1)||''});const result=await api('/api/collector/equipment-list?'+params);items=result.items;nextCursor=result.nextCursor;}
async function releaseLock(){clearInterval(lockTimer);if(lockToken&&equipment){const token=lockToken;lockToken=null;try{await api('/api/collector/equipment-unlock',{id:equipment.id,token});}catch{}}}
async function ensureInventoryOpen(){if(collection.sections.F.state==='Concluído'||collection.sections.G.state==='Concluído'){if(!await confirmAction('Reabrir equipamentos?','Os cartões F/G voltarão a Em andamento e precisarão ser concluídos manualmente novamente.'))return false;await api('/api/collector/inventory-section',{inspectionId:collection.inspection.id,section:'F',version:collection.sections.F.version,reopen:true});await loadCollection();}return true;}
async function discardBeforeReplacement(){if(equipment&&!equipment.saved&&equipment.touched){if(!await confirmAction('Descartar ficha ainda não salva?','Para retomar a ficha, cancele e use Retomar ficha em preenchimento. Confirmar descarta as respostas e prévias desta ficha.'))return false;const key=photoTarget('equipment',equipment.id);for(const photo of pendingPhotos.get(key)||[])URL.revokeObjectURL(photo.preview);pendingPhotos.delete(key);}return true;}
async function newEquipment(){if(!await discardBeforeReplacement()||!await leave()||!await ensureInventoryOpen())return;const previous=equipment?.data;if(equipment&&!pendingPhotos.get(photoTarget('equipment',equipment.id))?.length)photoLists.delete(photoTarget('equipment',equipment.id));equipment={id:crypto.randomUUID(),touched:false,data:{category:group==='G'?'projector':previous?.category||'',mode:'Individual',quantity:1,environment:previous?.environment||'',technical:{}}};equipmentVersion=0;lockToken=null;equipmentStep=0;dirty=false;view='equipment';notice='';errorFields={};repaint();}
async function editEquipment(id){if(!await discardBeforeReplacement()||!await leave()||!await ensureInventoryOpen())return;const result=await api('/api/collector/equipment-lock',{inspectionId:collection.inspection.id,id});lockToken=result.token;equipment={id,data:result.equipment.data};equipmentVersion=result.equipment.version;equipmentStep=0;dirty=false;view='equipment';await loadPhotos('equipment',id);lockTimer=setInterval(async()=>{if(!lockToken)return;try{const renewed=await api('/api/collector/equipment-lock',{inspectionId:collection.inspection.id,id,token:lockToken});lockToken=renewed.token;}catch(error){clearInterval(lockTimer);status('Edição expirada');toast(error.message);}},60000);repaint();}
async function persistEquipment(){const fields=validateEquipment(equipment.data,context());if(Object.keys(fields).length){errorFields=fields;const pages=equipmentSteps(),n=pages.findIndex(fs=>fs.some(f=>fields[f.key]));if(n>=0)equipmentStep=n;render();throw Error('Confira os campos destacados.');}status('Salvando equipamento…');const result=await api('/api/collector/equipment-save',{inspectionId:collection.inspection.id,id:equipment.id,data:equipment.data,version:equipmentVersion,lockToken,duplicateReason:equipment.duplicateReason});equipmentVersion=result.version;equipment.saved=true;dirty=false;status('Rascunho no servidor');await loadCollection();return result;}
async function loadPhotos(kind,id,inspectionId=collection.inspection.id){const result=await api('/api/collector/photo-list?'+new URLSearchParams({inspectionId,kind,targetId:id}));photoLists.set(photoTarget(kind,id),result.photos);}
async function preparePhoto(file){if(!file.type.startsWith('image/'))throw Error('Selecione somente fotografias.');if(file.size>30*1024*1024)throw Error('A imagem original excede 30 MB. Escolha uma versão menor.');const source=URL.createObjectURL(file);try{const image=new Image();image.src=source;await image.decode();const scale=Math.min(1,1600/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.round(image.naturalWidth*scale);canvas.height=Math.round(image.naturalHeight*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.85));if(!blob||blob.size>3*1024*1024)throw Error('Não foi possível otimizar a foto para envio. Escolha outra imagem.');return {id:crypto.randomUUID(),blob,preview:URL.createObjectURL(blob)};}finally{URL.revokeObjectURL(source);}}
async function uploadPhotos(key){const [kind,targetId]=key.split(':');const photoContext=photoContexts.get(key)||{inspectionId:collection.inspection.id};if(kind==='equipment'&&equipment?.id===targetId&&!equipment.saved)await persistEquipment();if(['occurrence','answer'].includes(kind)&&view==='group')await saveSection();if(!capabilities.photosEnabled)throw Error('Conecte o armazenamento antes de enviar. As prévias permanecem nesta aba.');const pending=pendingPhotos.get(key)||[];for(const photo of [...pending]){const response=await fetch('/api/collector/photo-upload',{method:'POST',headers:{'Content-Type':'image/jpeg','X-CSRF-Token':me.csrf,'X-Photo-Id':photo.id,'X-Inspection-Id':photoContext.inspectionId,'X-Target-Kind':kind,'X-Target-Id':targetId},body:photo.blob}),result=await response.json();if(!response.ok)throw Error(result.error||'Fotografia não confirmada. A prévia foi preservada.');pending.splice(pending.indexOf(photo),1);URL.revokeObjectURL(photo.preview);await loadPhotos(kind,targetId,photoContext.inspectionId);}render();toast('Fotografias recebidas pelo servidor.');}
async function accountMenu(){const d=document.createElement('dialog');d.innerHTML='<h2>'+esc(me.displayName||me.username)+'</h2><p>Conta individual de coleta</p><p class="help">Revisão 2 · 28/10/2026</p><p><a href="/conta">Minha conta e sessões</a></p><p><a href="/login" target="_blank" rel="noopener">Entrar novamente em outra aba</a></p>'+button('Sair','logout','secondary')+button('Fechar','close-dialog','text-button');document.body.append(d);d.showModal();}
app.addEventListener('input',event=>{const target=event.target;if(target.id==='unit-search'){unitQuery=target.value;$('#unit-results').innerHTML=unitResults();const count=$('[data-unit-filter-count]');if(count)count.textContent=visibleCollectorUnits(units,unitQuery,unitTab).length;return;}if(target.id==='equipment-search'){equipmentQuery=target.value;clearTimeout(saveTimer);saveTimer=setTimeout(()=>{cursors=[null];loadItems().then(render).catch(showError);},450);return;}if(target.closest('#environment-form')){environmentDraft[target.name]=target.value;return;}if(target.name?.startsWith('tech-')&&equipment){equipment.data.technical[target.name.slice(5)]=target.value;dirty=true;equipment.touched=true;status('Ficha ainda não salva');return;}if(target.dataset.field){set(currentData(),target.dataset.field,target.type==='checkbox'?target.checked:target.value);if(view==='group')scheduleSave();else{dirty=true;equipment.saved=false;equipment.touched=true;status('Ficha ainda não salva');}}});
app.addEventListener('change',async event=>{const target=event.target;try{if(target.id==='category-filter'||target.id==='verification-filter'){if(target.id==='category-filter')categoryFilter=target.value;else verificationFilter=target.value;cursors=[null];await loadItems();render();return;}const photoKey=target.dataset.photoFile||target.dataset.photoGallery;if(photoKey){if(pendingPhotos.get(photoKey)?.length&&photoContexts.get(photoKey)?.inspectionId!==collection.inspection.id)throw Error('Existem prévias de outra visita para este registro. Envie ou remova as anteriores antes de fotografar novamente.');const pending=pendingPhotos.get(photoKey)||[],saved=photoLists.get(photoKey)||[],files=[...target.files];if(pending.length+saved.length+files.length>5)throw Error('Até cinco fotografias por equipamento ou ocorrência.');const buffered=[...pendingPhotos.values()].flat().reduce((sum,p)=>sum+p.blob.size,0);if(buffered>40*1024*1024)throw Error('Envie as fotografias pendentes antes de capturar outras para preservar a memória do aparelho.');for(const file of files)pending.push(await preparePhoto(file));pendingPhotos.set(photoKey,pending);photoContexts.set(photoKey,{inspectionId:collection.inspection.id,unitId:collection.unit.id,caption:collection.unit.name+' · '+(view==='facade'?'Fachada':view==='equipment'?'Equipamento':group+' · Registro '+photoKey.split(':')[1])});if(equipment&&photoKey===photoTarget('equipment',equipment.id))equipment.touched=true;render();return;}if(target.type==='checkbox'&&target.dataset.field){set(currentData(),target.dataset.field,target.checked);if(view==='group')scheduleSave();render();}}catch(error){showError(error);}});
app.addEventListener('submit',async event=>{event.preventDefault();if(event.target.id!=='environment-form')return;const b=event.target.querySelector('button');b.disabled=true;try{await api('/api/collector/environment-save',{inspectionId:collection.inspection.id,...environmentDraft});environmentDraft={name:'',type:'Outro ambiente'};await loadCollection();render();toast('Ambiente cadastrado no servidor.');}catch(error){showError(error);}finally{b.disabled=false;}});
document.addEventListener('click',async event=>{const target=event.target.closest('button,[data-action]');if(!target)return;if(target.dataset.action==='close-dialog'){target.closest('dialog')?.close();target.closest('dialog')?.remove();return;}if(target.dataset.action==='logout'){if(!await confirmAction('Sair da coleta?','Confira se seus dados e fotografias foram enviados.'))return;try{if(view==='group'&&dirty)await saveSection();await api('/api/auth/logout',{});location.assign('/login');}catch(error){showError(error);}return;}if(!app.contains(target))return;if(busy)return;try{
 if(target.dataset.photoPicker){const selector=target.dataset.camera?'data-photo-file':'data-photo-gallery';app.querySelector('input['+selector+'="'+target.dataset.photoPicker+'"]').click();return;}
 if(target.dataset.sheet){openSheet(target);return;}
 if(target.dataset.choice){const data=currentData();set(data,target.dataset.choice,target.dataset.value);if(target.dataset.choice==='category'&&categories.find(c=>c[0]===data.category)?.[2]==='individual'){data.mode='Individual';data.quantity=1;}if(view==='group')scheduleSave();else{dirty=true;equipment.saved=false;}errorFields={};render();return;}
 const action=target.dataset.action;if(!action)return;
 busy=true;target.disabled=true;notice='';
 if(action==='unit-tab'){unitTab=target.dataset.tab;unitQuery='';repaint();}
 else if(action==='select-unit'){try{collection=await api('/api/collector/v3-start',{unitId:target.dataset.id});}catch(e){if(!e.legacyInspectionId)throw e;if(!await confirmAction('Iniciar uma nova coleta?','Há um rascunho anterior nesta unidade. Ele e seus equipamentos serão preservados no histórico. Confirmar inicia a coleta atual; cancelar retorna à lista de unidades.'))return;collection=await api('/api/collector/v3-start',{unitId:target.dataset.id,preservePrevious:true});}await loadCollection();if(['visita-2','coleta-2.0','coleta-3.0'].includes(collection.inspection.questionnaire_version))return;view='facade';notice='';status('Rascunho no servidor');repaint();}
 else if(action==='return-categories'){if(!await leave())return;view='cards';returnToReview=false;await loadCollection();repaint();}
 else if(action==='show-facade'){if(!await leave())return;view='facade';repaint();}
 else if(action==='start-identification'){group='A';if(collection.sections.A.state==='Concluído'){view='cards';repaint();await openGroup('A');}else{answers=structuredClone(collection.sections.A.data||{});step=0;view='group';repaint();}}
 else if(action==='add-evidence'){let key=target.dataset.evidence;if(target.dataset.evidenceRow){const row=get(answers,target.dataset.evidenceRow);row.id||=crypto.randomUUID();key=group+'.'+target.dataset.evidenceRow.replace(/\.\d+$/, '')+'.'+row.id;}answers._photoEvidence||={};answers._photoEvidence[key]||=crypto.randomUUID();scheduleSave();render();}
 else if(action==='account')await accountMenu();
 else if(action==='photo-queue'){if(!await leave())return;view='photo-queue';repaint();}
 else if(action==='open-group')await openGroup(target.dataset.group,target.dataset.errorKey||null);
 else if(action==='fab'){menu=!menu;render();}
 else if(action==='change-unit'){if([...pendingPhotos.values()].some(list=>list.length)){toast('Envie ou remova as prévias pendentes antes de trocar de unidade. Elas ainda estão somente nesta aba.');return;}if(equipment&&!equipment.saved&&equipment.touched&&!await confirmAction('Trocar de unidade?','A ficha ainda não salva será descartada. Cancele para retornar e salvá-la.'))return;if(!await leave())return;units=(await api('/api/units')).units;equipment=null;collection=null;unitQuery='';unitTab='pending';view='units';saveLabel='';repaint();}
 else if(action==='cards'||action==='back'){if(!await leave())return;if(returnToReview&&['group','inventory'].includes(view)){await showReview();return;}view=collection?'cards':'units';returnToReview=false;await (collection?loadCollection():Promise.resolve());repaint();}
 else if(action==='next'||action==='previous'){await saveSection();step+=action==='next'?1:-1;if(step<0){if(returnToReview){await showReview();return;}view='cards';step=0;}errorFields={};repaint();}
 else if(action==='save-section'){await saveSection();toast('Rascunho confirmado pelo servidor.');}
 else if(action==='complete-section'){const startInternet=group==='A'&&!returnToReview;await saveSection(true);if(startInternet)await openGroup('C');}
 else if(action==='open-environments')await openGroup('B');
 else if(action==='inventory'){verificationFilter='';await openGroup('F');}
 else if(action==='show-unverified'){verificationFilter='unverified';await openGroup('F');}
 else if(action==='new-equipment')await newEquipment();
 else if(action==='resume-equipment'){if(equipmentVersion>0&&!lockToken){const acquired=await api('/api/collector/equipment-lock',{inspectionId:collection.inspection.id,id:equipment.id});lockToken=acquired.token;if(acquired.equipment.version!==equipmentVersion){await releaseLock();throw Object.assign(Error('Outra sessão alterou esta ficha. Suas respostas continuam nesta aba; compare antes de salvar.'),{conflict:true,server:acquired.equipment.data});}}view='equipment';repaint();}
 else if(action==='edit-equipment')await editEquipment(target.dataset.id);
 else if(action==='equipment-next'){if(equipmentStep===1&&!equipment.data.environment){errorFields={environment:'Cadastre e selecione o ambiente no grupo B.'};render();return;}equipmentStep=Math.min(5,equipmentStep+1);errorFields={};repaint();}
 else if(action==='equipment-previous'){if(equipmentStep>0){equipmentStep--;repaint();}else{if(await leave()){group='F';view='inventory';await loadItems();repaint();}}}
 else if(action==='save-equipment'||action==='save-add-another'){await persistEquipment();const key=photoTarget('equipment',equipment.id);if(pendingPhotos.get(key)?.length)await uploadPhotos(key);await releaseLock();toast('Equipamento salvo no servidor.');if(action==='save-add-another'){dirty=false;await newEquipment();}else{equipment=null;view='cards';repaint();}}
 else if(action==='justify-duplicate'){const reason=prompt('Por que este é outro equipamento? A duplicidade ficará em análise administrativa.');if(reason?.trim()){equipment.duplicateReason=reason.trim();await persistEquipment();toast('Registro salvo para análise, sem dupla contagem oficial.');render();}}
 else if(action==='fill-asset'){equipment.data.asset='Sem patrimônio';equipment.saved=false;dirty=true;render();}
 else if(action==='fill-serial'){equipment.data.serial='Sem número de série';equipment.saved=false;dirty=true;render();}
 else if(action==='fill-identification'){equipment.data.brand='Não identificado';equipment.data.model='Não identificado';equipment.saved=false;dirty=true;render();}
 else if(action==='add-row'){const path=target.dataset.path,list=get(currentData(),path)||[];list.push({id:crypto.randomUUID()});set(currentData(),path,list);scheduleSave();render();}
 else if(action==='remove-row'){if(!await confirmAction('Remover registro do rascunho?','A alteração ficará registrada no histórico ao salvar.'))return;get(currentData(),target.dataset.path).splice(Number(target.dataset.index),1);scheduleSave();render();}
 else if(action==='upload-photos')await uploadPhotos(target.dataset.target);
 else if(action==='remove-preview'){const list=pendingPhotos.get(target.dataset.target);const [photo]=list.splice(Number(target.dataset.index),1);URL.revokeObjectURL(photo.preview);render();}
 else if(action==='remove-photo'){if(!await confirmAction('Remover foto do rascunho?','A fotografia selecionada será removida.'))return;await api('/api/collector/photo-remove',{id:target.dataset.id});const [kind,id]=target.dataset.target.split(':');await loadPhotos(kind,id);render();}
 else if(action==='next-page'){if(nextCursor){cursors.push(nextCursor);await loadItems();repaint();}}
 else if(action==='previous-page'){if(cursors.length>1){cursors.pop();await loadItems();repaint();}}
 else if(action==='complete-inventory'){await api('/api/collector/inventory-section',{inspectionId:collection.inspection.id,section:group,version:collection.sections[group].version});await loadCollection();view='cards';repaint();}
 else if(action==='verify-equipment'){const result=target.dataset.result,reason=result==='Não localizado'?prompt('Justificativa obrigatória para não localização:'):result==='Não verificado'?prompt('Justificativa opcional:')||'':'';if(result==='Não localizado'&&!reason?.trim())return;await api('/api/collector/verify',{inspectionId:collection.inspection.id,id:target.dataset.id,result,reason});await loadItems();render();toast('Verificação registrada no servidor.');}
 else if(action==='review'){if(!await leave())return;await showReview();}
 else if(action==='finish'){if(!await confirmAction('Concluir vistoria?','Os dados obrigatórios serão confirmados pelo servidor e disponibilizados ao painel.'))return;const result=await api('/api/collector/finish',{inspectionId:collection.inspection.id,revision:reviewData.revision,confirm:true});if(result.completed){await loadCollection();view='cards';equipment=null;repaint();toast('Vistoria concluída e recebida pelo servidor.');}}
 }catch(error){showError(error);}finally{busy=false;target.disabled=false;}});
function openSheet(target){const path=target.dataset.sheet,type=target.dataset.sheetType,fieldOptions=JSON.parse(target.dataset.options||'[]');const options=['environment','environments'].includes(type)?collection.environments.map(e=>[e.id,e.name]):fieldOptions.filter(v=>path!=='category'||group!=='G'||audiovisual.includes(v)).map(v=>[v,path==='category'?categoryName(v):v]);const data=currentData(),selected=type==='environments'?[...(get(data,path)||[])]:get(data,path),dialog=document.createElement('dialog');dialog.className='bottom-sheet';dialog.innerHTML='<h2>'+esc(target.dataset.title)+'</h2><input type="search" placeholder="Pesquisar" aria-label="Pesquisar opção"><div class="sheet-options"></div><div class="actions">'+button('Cancelar','close-dialog','secondary')+(type==='environments'?'<button class="primary" id="apply-selection">Aplicar seleção</button>':'')+'</div>';const box=dialog.querySelector('.sheet-options');const draw=query=>{box.innerHTML=options.filter(([,label])=>label.toLowerCase().includes(query.toLowerCase())).map(([id,label])=>'<button type="button" class="'+((type==='environments'?selected.includes(id):selected===id)?'selected':'')+'" data-option="'+esc(id)+'">'+esc(label)+((type==='environments'&&selected.includes(id))?' ✓':'')+'</button>').join('')||'<p>Nenhuma opção encontrada.</p>'+(['environment','environments'].includes(type)?'<button type="button" id="sheet-open-environments" class="secondary">Cadastrar ambiente no cartão B</button>':'');const shortcut=dialog.querySelector('#sheet-open-environments');if(shortcut)shortcut.onclick=()=>{dialog.close();dialog.remove();openGroup('B').catch(showError);};};draw('');dialog.querySelector('input').oninput=e=>draw(e.target.value);dialog.onclick=e=>{const option=e.target.closest('[data-option]');if(!option)return;const value=option.dataset.option;if(type==='environments'){const i=selected.indexOf(value);if(i>=0)selected.splice(i,1);else selected.push(value);draw(dialog.querySelector('input').value);}else{set(data,path,value);if(path==='category'&&categories.find(c=>c[0]===value)?.[2]==='individual'){data.mode='Individual';data.quantity=1;}dialog.close();dialog.remove();if(view==='group')scheduleSave();else{dirty=true;equipment.saved=false;}render();}};if(type==='environments')dialog.querySelector('#apply-selection').onclick=()=>{set(data,path,selected);dialog.close();dialog.remove();if(view==='group')scheduleSave();else{dirty=true;equipment.saved=false;}render();};document.body.append(dialog);dialog.showModal();}
window.addEventListener('beforeunload',event=>{if(dirty||(equipment&&!equipment.saved&&equipment.touched)||[...pendingPhotos.values()].some(p=>p.length)){event.preventDefault();event.returnValue='';}});
window.addEventListener('offline',()=>status('Sem conexão · não enviado'));
window.addEventListener('online',()=>{toast('Conexão disponível. Confira e salve os dados pendentes.');});
try{me=await api('/api/auth/me');if(me.mustChange)location.replace('/conta');else{capabilities=await api('/api/collector/capabilities');units=(await api('/api/units')).units;navigation=installCollectorHistory(readRoute,restoreRoute,showError);await navigation.restore(navigation.initial());}}catch(error){if(!me)location.replace('/login');else showError(error);}

